(() => {
'use strict';
const API_BASE = window.ABUAD_LIFE_API || (location.hostname==='abuad-life.onrender.com' ? 'https://abuad-life-api.onrender.com' : location.origin);
const WS_BASE = API_BASE.replace(/^http/,'ws');
const KEY='abuadLifeSocial';
let cloudRevision=null;
let social={token:'',profile:null,players:[],online:[],messages:[],dm:{},view:'chat',selected:null,connected:false,error:''};
try{social={...social,...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch{}
const esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function saveSocial(){localStorage.setItem(KEY,JSON.stringify({token:social.token,profile:social.profile}))}
async function api(path,opt={}){const headers={'Content-Type':'application/json',...(opt.headers||{})};if(social.token)headers.Authorization='Bearer '+social.token;const res=await fetch(API_BASE+path,{...opt,headers});const data=await res.json().catch(()=>({}));if(!res.ok){const err=new Error(data.error||'Request failed');err.status=res.status;throw err;}return data}
function toastMsg(m){if(window.toast)toast(m);else alert(m)}
let ws=null,reconnect=null;
function connect(){if(!social.token||ws&&ws.readyState<2)return;clearTimeout(reconnect);ws=new WebSocket(WS_BASE+'/ws?token='+encodeURIComponent(social.token));ws.onopen=()=>{social.connected=true;renderSocialButton();renderSocial()};ws.onclose=()=>{social.connected=false;renderSocialButton();reconnect=setTimeout(connect,2500)};ws.onmessage=e=>{try{const p=JSON.parse(e.data);if(p.type==='message'&&p.room==='campus'){social.messages=[...social.messages,p.message].slice(-80);renderSocial()}if(p.type==='online'){social.online=p.online||[];renderSocialButton();renderSocial()}if(p.type==='profile'){social.players=social.players.map(x=>x.id===p.profile.id?p.profile:x);if(social.profile?.id===p.profile.id)social.profile=p.profile;renderSocial()}if(p.type==='dm'){const other=p.message.sender_id===social.profile?.id?p.message.receiver_id:p.message.sender_id;social.dm[other]=[...(social.dm[other]||[]),p.message].slice(-80);renderSocial()}}catch{}}}
async function bootstrap(){if(!social.token)return;try{const me=await api('/api/me');social.profile=me.profile;social.online=me.online||[];const [players,msgs]=await Promise.all([api('/api/players'),api('/api/messages')]);social.players=players.players||[];social.online=players.online||social.online;social.messages=msgs.messages||[];saveSocial();connect();cloudRevision=null}catch(e){social.error=e.message;if(e.status===401){social.token='';social.profile=null;saveSocial()}}renderSocialButton();renderSocial()}
function renderSocialButton(){const b=document.querySelector('#socialLaunch');if(!b)return;const count=Array.isArray(social.online)?social.online.length:0;b.innerHTML=`💬 <span>${social.profile?'Campus chat': 'Join chat'}${count?` · ${count}`:''}</span>`;b.classList.toggle('online',social.connected)}
function authHtml(){return `<div class="social-panel"><h2>Join Abuad Life Online</h2><p>Create a player profile to chat with other students in real time. Use a password you do not use elsewhere.</p><div class="social-tabs"><button class="active" data-auth-tab="register">Create account</button><button data-auth-tab="login">Sign in</button></div><form class="social-auth" id="socialAuth"><input name="username" aria-label="Username" placeholder="Username" maxlength="24"><input name="email" aria-label="Email" type="email" placeholder="Email"><input name="password" aria-label="Password" type="password" placeholder="Password, minimum 8 characters"><select name="department" aria-label="Department"><option>Computer Science</option><option>Engineering</option><option>Medicine</option><option>Nursing</option><option>Law</option><option>Pharmacy</option><option>Agriculture</option><option>Business Administration</option><option>Arts & Sciences</option></select><select name="level" aria-label="Level"><option>100 Level</option><option>200 Level</option><option>300 Level</option><option>400 Level</option><option>500 Level</option></select><input name="avatar" aria-label="Avatar emoji" placeholder="Avatar emoji" value="🧑🏾‍🎓" maxlength="4"><button>Create profile</button></form><small>${esc(social.error||'Profiles and messages are stored in the Abuad Life database.')}</small></div>`}
function signedHtml(){const p=social.profile||{};const onlineIds=new Set((social.online||[]).map(x=>x.id||x));return `<div class="social-grid"><section class="social-panel"><div class="social-me"><span class="social-avatar">${esc(p.avatar||'🧑🏾‍🎓')}</span><div><strong>${esc(p.username)}</strong><div class="social-status"><span class="online-dot"></span>${social.connected?'Online now':'Connecting'} · ${esc(p.department||'Student')}</div></div></div><div class="social-tabs"><button class="${social.view==='chat'?'active':''}" data-social-view="chat">Campus</button><button class="${social.view==='people'?'active':''}" data-social-view="people">People</button><button class="${social.view==='profile'?'active':''}" data-social-view="profile">Profile</button></div>${sideHtml(onlineIds)}</section><section class="chat-panel">${mainHtml(onlineIds)}</section></div>`}
function sideHtml(onlineIds){if(social.view==='profile')return `<form class="profile-edit" id="profileEdit"><input name="avatar" aria-label="Avatar emoji" value="${esc(social.profile.avatar)}" maxlength="4"><input name="department" aria-label="Department" value="${esc(social.profile.department)}" placeholder="Department"><input name="level" aria-label="Level" value="${esc(social.profile.level)}" placeholder="Level"><textarea name="bio" aria-label="Short bio" placeholder="Short bio" maxlength="180">${esc(social.profile.bio)}</textarea><button>Save profile</button><p id="cloudStatus">Cloud saves are private to your account.</p><button type="button" id="cloudUpload">Save this character to cloud</button><button type="button" id="cloudLoad">Load cloud character</button><button type="button" class="ghost" id="logoutSocial">Sign out</button></form>`;return `<h3>Students online</h3><div class="player-list">${(social.players||[]).map(p=>`<button class="player-row" data-player="${p.id}"><span>${esc(p.avatar||'🧑🏾‍🎓')}</span><span><strong>${esc(p.username)}</strong><small>${onlineIds.has(p.id)?'🟢 Online':'Last seen'} · ${esc(p.department||'Student')}</small></span></button>`).join('')||'<p>No players yet.</p>'}</div>`}
function mainHtml(onlineIds){if(social.view==='people'&&social.selected){const p=social.players.find(x=>x.id===social.selected);if(!p)return '<p>Select a student to open their profile.</p>';const dm=social.dm[p.id]||[];return `<div class="dm-title"><span class="social-avatar">${esc(p.avatar)}</span><div><h2>${esc(p.username)}</h2><small>${onlineIds.has(p.id)?'Online now':'Offline'} · ${esc(p.level||'')}</small></div></div><p>${esc(p.bio||'No bio yet.')}</p><div class="profile-actions"><button data-block="${p.id}" class="ghost">Block</button><button data-report="${p.id}" class="ghost">Report</button></div><div class="chat-log">${dm.map(m=>msgHtml(m,m.sender_id===social.profile.id)).join('')}</div><form class="dm-input" id="dmForm"><input name="body" aria-label="Message" maxlength="500" placeholder="Message ${esc(p.username)}"><button>Send</button></form>`}return `<h2>Campus chat</h2><p>Real players only. Be respectful; reports are stored for moderation.</p><div class="chat-log" id="chatLog">${(social.messages||[]).map(m=>msgHtml(m,m.sender_id===social.profile.id)).join('')}</div><form class="chat-compose" id="chatForm"><input name="body" aria-label="Message" maxlength="500" placeholder="Say something on campus..."><button>Send</button></form>`}
function msgHtml(m,me){return `<div class="msg ${me?'me':''}"><strong>${esc(m.avatar||'')} ${esc(m.username||'Student')}</strong><div>${esc(m.body)}</div><small>${new Date(m.created_at||Date.now()).toLocaleString()}</small></div>`}
function renderSocial(){const modal=document.querySelector('#modal');if(!modal||!modal.open||!modal.classList.contains('social-modal'))return;modal.className='social-modal';const drafts=[...modal.querySelectorAll('input,textarea')].map(e=>({name:e.name,value:e.value,focused:e===document.activeElement,start:e.selectionStart}));modal.innerHTML=`<button class="modal-x" id="closeSocial" aria-label="Close">×</button>${social.token&&social.profile?signedHtml():authHtml()}`;bindSocial();for(const d of drafts){const el=[...modal.querySelectorAll('input,textarea')].find(e=>e.name===d.name);if(el){el.value=d.value;if(d.focused){el.focus();try{el.setSelectionRange(d.start,d.start)}catch{}}}}}
function openSocial(){const modal=document.querySelector('#modal');modal.className='social-modal';if(!modal.open)modal.showModal();renderSocial()}
function bindSocial(){const close=document.querySelector('#closeSocial');if(close)close.onclick=()=>document.querySelector('#modal').close();document.querySelectorAll('[data-social-view]').forEach(b=>b.onclick=()=>{social.view=b.dataset.socialView;social.selected=null;renderSocial()});document.querySelectorAll('[data-player]').forEach(b=>b.onclick=async()=>{social.view='people';social.selected=b.dataset.player;if(!social.dm[social.selected])try{social.dm[social.selected]=(await api('/api/dm/'+social.selected)).messages||[]}catch(e){toastMsg(e.message)}renderSocial()});const form=document.querySelector('#socialAuth');if(form)form.onsubmit=async e=>{e.preventDefault();const fd=Object.fromEntries(new FormData(form));try{const out=await api('/api/auth/register',{method:'POST',body:JSON.stringify(fd)});social.token=out.token;social.profile=out.profile;saveSocial();await bootstrap();toastMsg('Profile created. Welcome online!')}catch(err){toastMsg(err.message)}};document.querySelectorAll('[data-auth-tab]').forEach(b=>b.onclick=()=>{const login=b.dataset.authTab==='login';document.querySelectorAll('[data-auth-tab]').forEach(x=>x.classList.toggle('active',x===b));form.innerHTML= login?'<input name="login" aria-label="Email or username" placeholder="Email or username"><input name="password" aria-label="Password" type="password" placeholder="Password"><button>Sign in</button>':'<input name="username" aria-label="Username" placeholder="Username" maxlength="24"><input name="email" aria-label="Email" type="email" placeholder="Email"><input name="password" aria-label="Password" type="password" placeholder="Password, minimum 8 characters"><select name="department" aria-label="Department"><option>Computer Science</option><option>Engineering</option><option>Medicine</option><option>Nursing</option><option>Law</option><option>Pharmacy</option><option>Agriculture</option><option>Business Administration</option><option>Arts & Sciences</option></select><select name="level" aria-label="Level"><option>100 Level</option><option>200 Level</option><option>300 Level</option><option>400 Level</option><option>500 Level</option></select><input name="avatar" aria-label="Avatar emoji" placeholder="Avatar emoji" value="🧑🏾‍🎓" maxlength="4"><button>Create profile</button>';form.onsubmit=async e=>{e.preventDefault();const fd=Object.fromEntries(new FormData(form));try{const out=await api(login?'/api/auth/login':'/api/auth/register',{method:'POST',body:JSON.stringify(fd)});social.token=out.token;social.profile=out.profile;saveSocial();await bootstrap();toastMsg(login?'Signed in.':'Profile created.')}catch(err){toastMsg(err.message)}}});const chat=document.querySelector('#chatForm');if(chat)chat.onsubmit=async e=>{e.preventDefault();const body=chat.body.value.trim();if(!body)return;chat.body.value='';try{await api('/api/messages',{method:'POST',body:JSON.stringify({body,room:'campus'})})}catch(err){toastMsg(err.message)}};const dm=document.querySelector('#dmForm');if(dm)dm.onsubmit=async e=>{e.preventDefault();const body=dm.body.value.trim();if(!body)return;dm.body.value='';try{await api('/api/dm/'+social.selected,{method:'POST',body:JSON.stringify({body})})}catch(err){toastMsg(err.message)}};const edit=document.querySelector('#profileEdit');if(edit)edit.onsubmit=async e=>{e.preventDefault();try{const out=await api('/api/me',{method:'PATCH',body:JSON.stringify(Object.fromEntries(new FormData(edit)))});social.profile=out.profile;saveSocial();toastMsg('Profile updated.');renderSocial()}catch(err){toastMsg(err.message)}};const logout=document.querySelector('#logoutSocial');if(logout)logout.onclick=()=>{social.token='';social.profile=null;social.messages=[];social.dm={};social.players=[];social.online=[];social.selected=null;cloudRevision=null;saveSocial();clearTimeout(reconnect);if(ws)ws.close();renderSocialButton();renderSocial()};document.querySelectorAll('[data-block]').forEach(b=>b.onclick=async()=>{await api('/api/block/'+b.dataset.block,{method:'POST'});toastMsg('Player blocked.')});document.querySelectorAll('[data-report]').forEach(b=>b.onclick=async()=>{const reason=prompt('Why are you reporting this player?');if(!reason?.trim())return;await api('/api/report/'+b.dataset.report,{method:'POST',body:JSON.stringify({reason})});toastMsg('Report saved for moderation.')});bindCloud();const log=document.querySelector('#chatLog');if(log)log.scrollTop=log.scrollHeight}
async function cloudRead(){const out=await api('/api/save');return out.save}
function bindCloud(){
 const upload=document.querySelector('#cloudUpload'),download=document.querySelector('#cloudLoad');
 if(upload)upload.onclick=async()=>{upload.disabled=true;try{
 const state=window.AbuadLifeGame?.snapshot();if(!state)throw new Error('Create a character first.');
 if(cloudRevision===null){const existing=await cloudRead();if(existing){toastMsg('A cloud character already exists. Load it first to continue safely.');return}cloudRevision=0}
 const out=await api('/api/save',{method:'PUT',body:JSON.stringify({state,revision:cloudRevision})});cloudRevision=out.revision;toastMsg('Character saved to your account.');
 }catch(e){toastMsg(e.message)}finally{upload.disabled=false}};
 if(download)download.onclick=async()=>{download.disabled=true;try{
 const saved=await cloudRead();if(!saved)throw new Error('No cloud character yet. Save your current character first.');
 if(!confirm('Load your cloud character? Your current browser character will be backed up first.'))return;
 const current=window.AbuadLifeGame?.snapshot();if(current)localStorage.setItem('abuad-life-backup-'+social.profile.id,JSON.stringify(current));
 window.AbuadLifeGame.restore(saved.state);cloudRevision=saved.revision;toastMsg('Cloud character loaded.');
 }catch(e){toastMsg(e.message)}finally{download.disabled=false}};
}
const ready=()=>{const b=document.querySelector('#socialLaunch');if(b)b.onclick=openSocial;bootstrap();renderSocialButton()};if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',ready);else ready();window.AbuadLifeSocial={open:openSocial,bootstrap,apiBase:API_BASE};
})();
